                } else if (d.signing === 'continue') {
                    var pSuccess = 0.2 + 0.3 * clamp(ds.counterpartyTrust + trustChange, 0, 100) / 100;
                    if (Math.random() < pSuccess) {
                        value *= 1.08; clausesGained = 20; trustChange -= 6; signingOutcome = 'pushed_success';
                    } else {
                        value *= 0.5; trustChange -= 12; signingOutcome = 'pushed_backfired';
                    }
                } else {
                    ds.dealSigned = true;
                    signingOutcome = 'signed';
                }
            }

            value = Math.round(value);
            clausesGained = Math.max(0, Math.min(clausesGained, 20 - ds.clausesResolved));
            var trustEnd = clamp(ds.counterpartyTrust + trustChange, 0, 100);
            // low trust at close: the counterparties price a risk discount into the whole deal
            var riskDiscount = 0;
            if (state.currentPeriod >= 4 && signingOutcome !== 'walked_away' && trustEnd < 50) {
                riskDiscount = Math.round((ds.dealValue + value) * (0.2 - 0.4 * trustEnd / 100));
            }

            ds.dealValue += value - riskDiscount;
            ds.riskDiscount = riskDiscount;
            ds.clausesResolved += clausesGained;
            ds.counterpartyTrust = trustEnd;
            ds.bargainingPower = clamp(ds.bargainingPower + powerChange, 0, 100);
            ds.lastStance = d.stance;
            ds.signingOutcome = signingOutcome;
            if (signingOutcome === 'walked_away') { ds.walkedAway = true; ds.negotiatedValue = ds.dealValue; }

            ds.dealValueHistory.push(ds.dealValue);
            ds.trustHistory.push(ds.counterpartyTrust);
            ds.powerHistory.push(ds.bargainingPower);
            ds.clausesHistory.push(ds.clausesResolved);

            var score = this._composite(ds);
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: score });

            var self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext, domainState: ds });
            })(state.currentPeriod + 1), 500);

            return { value: value, clauses: clausesGained, trustChange: trustChange, powerChange: powerChange, outcome: signingOutcome, score: score };
        }

        // One composite for the platform grade, the debrief and the verdict (0-100, clamped)
        _scoreParts(ds) {
            var clamp = function(v, a, b) { return Math.max(a, Math.min(b, v)); };
            var o = ds.signingOutcome || 'in_progress';
            var walked = o === 'walked_away';
            var v = walked ? this.BATNA_VALUE : (ds.dealValue || 0);
            var valuePts = 30 * clamp((v - this.V_FLOOR) / (this.V_TARGET - this.V_FLOOR), 0, 1);
            var clausePts = walked ? 0 : 25 * (ds.clausesResolved || 0) / 20;
            var trustPts = 15 * (ds.counterpartyTrust || 0) / 100;
            var powerPts = 10 * (ds.bargainingPower || 0) / 100;
            var closePts = 0;
            if (o === 'signed') closePts = (ds.counterpartyTrust >= 55 && ds.clausesResolved >= 17) ? 20 : 12;
            else if (o === 'pushed_success') closePts = 12;
            else if (walked) closePts = (ds.negotiatedValue < this.BATNA_VALUE) ? 20 : 0;
            return { value: valuePts, clauses: clausePts, trust: trustPts, power: powerPts, close: closePts };
        }

        _composite(ds) {
            var p = this._scoreParts(ds);
            return Math.max(0, Math.min(100, Math.round(p.value + p.clauses + p.trust + p.power + p.close)));
        }

        _tierFor(score) {
            if (score >= 87) return 'master';
            if (score >= 72) return 'skilled';
            if (score >= 55) return 'competent';
            if (score >= 35) return 'developing';
            return 'novice';
        }

        _lang() {
            try { if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang; } catch (e) {}
            var h = document.documentElement && document.documentElement.lang;
            return h || 'en';
        }

        _money(v) {
            var l = this._lang() === 'es' ? 'es-ES' : 'en-GB';
            return '€' + (Math.round((v || 0) / 1000) * 1000).toLocaleString(l);
        }

        _tt(key, vars) {
            var s = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(key) : key;
            Object.keys(vars || {}).forEach(function(k) { s = s.split('{' + k + '}').join(vars[k]); });
            return s;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var st = (window.mySimulation && window.mySimulation.state) || {};
            var ds = st.domainState || {};
            var last = history[history.length - 1].results || {};
            if (ds.dealValue === undefined) {
                ds = { dealValue: last.totalDealValue || 0, clausesResolved: last.clausesResolved || 0, counterpartyTrust: last.trust || 0, bargainingPower: last.power || 0, signingOutcome: last.signingOutcome, negotiatedValue: last.totalDealValue || 0 };
            }
            var self = this;
            var score = this._composite(ds);
            var parts = this._scoreParts(ds);
            var tier = this._tierFor(score);
            var decs = history.map(function(h) { return h.decisions || {}; });
            var res = history.map(function(h) { return h.results || {}; });
            var outcome = ds.signingOutcome || last.signingOutcome;

            // what this player actually did, read from the run's history
            var aggRounds = [], revealRound = 0, withholdN = 0, offAgenda = 0, concSum = 0;
            decs.forEach(function(d, i) {
                if (d.stance === 'aggressive') aggRounds.push(i + 1);
                if (d.infoStrategy === 'reveal' && !revealRound) revealRound = i + 1;
                if (d.infoStrategy === 'withhold') withholdN++;
                var r = self.ROUNDS[Math.min(i, self.ROUNDS.length - 1)];
                if (r.agenda.indexOf(d.focus) < 0) offAgenda++;
                concSum += (+d.concession || 0);
            });
            var avgConc = Math.round(concSum / decs.length);
            var mistakes = [];
            if (aggRounds.length >= 2) mistakes.push({ round: aggRounds[1], key: 'ins_positional', vars: { n: aggRounds.length } });
            if (revealRound) mistakes.push({ round: revealRound, key: 'ins_reveal', vars: { r: revealRound } });
            if (avgConc >= 70) mistakes.push({ round: 1, key: 'ins_accommodate', vars: { c: avgConc } });
            if (outcome === 'pushed_backfired' || outcome === 'pushed_success') mistakes.push({ round: 4, key: outcome === 'pushed_backfired' ? 'ins_push_failed' : 'ins_push_lucky', vars: {} });
            if (outcome === 'walked_away' && ds.negotiatedValue >= this.BATNA_VALUE) mistakes.push({ round: 4, key: 'ins_walk_weak', vars: { v: this._money(ds.negotiatedValue), b: this._money(this.BATNA_VALUE) } });

            var insights = [];
            mistakes.forEach(function(m) { insights.push(self._tt(m.key, m.vars)); });
            if (outcome === 'walked_away' && ds.negotiatedValue < this.BATNA_VALUE) insights.push(this._tt('ins_walk_right', { v: this._money(ds.negotiatedValue) }));
            if (withholdN >= 3) insights.push(this._tt('ins_withhold', { n: withholdN }));
            if (offAgenda >= 2) insights.push(this._tt('ins_off_agenda', { n: offAgenda }));
            if (ds.riskDiscount > 0) insights.push(this._tt('ins_risk_discount', { v: this._money(ds.riskDiscount) }));
            if (aggRounds.length === 1 && aggRounds[0] === 1 && decs[1] && decs[1].stance !== 'aggressive') insights.push(this._tt('ins_anchor_pivot', {}));
            if (outcome === 'signed' && !mistakes.length) insights.push(this._tt('ins_close_good', { t: Math.round(ds.counterpartyTrust) }));
            insights.push(this._tt('ins_kpis', { v: this._money(outcome === 'walked_away' ? 0 : ds.dealValue), c: outcome === 'walked_away' ? 0 : (ds.clausesResolved || 0), t: Math.round(ds.counterpartyTrust || 0), p: Math.round(ds.bargainingPower || 0) }));
            insights = insights.slice(0, 5);

            var turning;
            if (mistakes.length) {
                var first = mistakes.slice().sort(function(a, b) { return a.round - b.round; })[0];
                turning = this._tt('turn_mistake', { r: first.round, what: this._tt(first.key + '_short', {}) });
            } else {
                var best = 0, bestR = 1;
                res.forEach(function(r, i) { if ((r.clausesGained || 0) + (r.trustChange || 0) / 4 > best) { best = (r.clausesGained || 0) + (r.trustChange || 0) / 4; bestR = i + 1; } });
                turning = this._tt('turn_good', { r: bestR });
            }

            return {
                totalDealValue: outcome === 'walked_away' ? 0 : ds.dealValue,
                clausesResolved: outcome === 'walked_away' ? 0 : ds.clausesResolved,
                counterpartyTrust: ds.counterpartyTrust,
                bargainingPower: ds.bargainingPower,
                dealSigned: outcome === 'signed' || outcome === 'pushed_success',
                signingOutcome: outcome,
                score: score, composite: score, overallScore: score, totalScore: score,
                outcomeScore: Math.round(parts.value + parts.clauses + parts.close),
                processScore: Math.round(parts.trust + parts.power),
                performance: tier,
                performanceKey: 'tier_' + tier,
                performanceLabel: this._tt('tier_' + tier, {}),
                turningPoint: turning,
                insights: insights,
                questions: [this._tt('q1', {}), this._tt('q2', {}), this._tt('q3', {})]
            };
        }

        formatCompletionMessage(summary) {
            if (!summary || summary.score === undefined) return '<div class="clausework-sim-cm"><p>' + this._tt('cm_done', {}) + '</p></div>';
            var esc = function(s) { return String(s == null ? '' : s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;').split(String.fromCharCode(34)).join('&quot;'); };
            var kpi = function(label, val) { return '<div class="clausework-sim-cm-kpi"><span>' + esc(label) + '</span><strong>' + esc(val) + '</strong></div>'; };
            var h = '<div class="clausework-sim-cm" role="region" aria-label="' + esc(this._tt('cm_title', {})) + '">';
            h += '<h2 class="clausework-sim-cm-score">' + summary.score + '/100</h2>';
            h += '<p class="clausework-sim-cm-verdict">' + esc(summary.performanceLabel) + '</p>';
            h += '<p class="clausework-sim-cm-sub">' + esc(this._tt('cm_sub', { o: summary.outcomeScore, p: summary.processScore })) + '</p>';
            h += '<div class="clausework-sim-cm-kpis">' +
                kpi(this._tt('deal_value_label', {}), this._money(summary.totalDealValue)) +
                kpi(this._tt('clauses_label', {}), (summary.clausesResolved || 0) + ' / 20') +
                kpi(this._tt('trust_label', {}), Math.round(summary.counterpartyTrust || 0) + '%') +
                kpi(this._tt('power_label', {}), Math.round(summary.bargainingPower || 0) + '%') +
                kpi(this._tt('signing_label', {}), this._tt('out_' + summary.signingOutcome, {})) + '</div>';
            h += '<h3>' + esc(this._tt('cm_turning', {})) + '</h3><p>' + esc(summary.turningPoint) + '</p>';
            h += '<h3>' + esc(this._tt('cm_insights', {})) + '</h3><ul>' + (summary.insights || []).map(function(s) { return '<li>' + esc(s) + '</li>'; }).join('') + '</ul>';
            h += '<h3>' + esc(this._tt('cm_questions', {})) + '</h3><ol>' + (summary.questions || []).map(function(s) { return '<li>' + esc(s) + '</li>'; }).join('') + '</ol>';
            return h + '</div>';
        }

